class InputString:
    def __init__(self, value):
        self.originalValue = value

class ReversedString:
    def __init__(self, value):
        self.reversedValue = value

class StringReverser:
    def reverse(self, input_string_object):
        return ReversedString(input_string_object.originalValue[::-1])

class StringProcessor:
    def process(self, original_str):
        initial_input = InputString(original_str)
        reverser_engine = StringReverser()
        processed_result = reverser_engine.reverse(initial_input)
        return processed_result.reversedValue

class ResultFormatter:
    def format(self, reversed_value):
        return reversed_value

def reverse_string(s):
    processor = StringProcessor()
    reversed_output = processor.process(s)
    formatter = ResultFormatter()
    final_result = formatter.format(reversed_output)
    return final_result

