class FactorialCalculator:
    def __init__(self):
        pass

    def compute(self, n):
        if n < 0:
            raise ValueError("Factorial is not defined for negative numbers.")

        result = FactorialResult(1)
        for i in range(1, n + 1):
            term = FactorialTerm(i)
            result.value *= term.value
        return result.value

