    def aggregate(self, numbers):
        current_sum = 0
        for num in numbers:
            current_sum += num
        return current_sum

class ItemCounter:
    def count(self, items):
        current_count = 0
        for _ in items:
            current_count += 1
        return float(current_count)

class ResultFormatter:
