        return float(value)

def calculate_average(numbers):
    number_collection = NumberList(numbers)
    calculator_instance = AverageCalculator()
    raw_average = calculator_instance.calculate(number_collection)
    formatted_average = ResultFormatter().format_output(raw_average)
    return formatted_average

