class NumberOperand:
    def __init__(self, value):
        self.numericValue = value

class OperationSymbol:
    def __init__(self, symbol):
        self.operatorChar = symbol

class CalculationResult:
    def __init__(self, result):
        self.calculatedValue = result

class ErrorMessage:
    def __init__(self, message):
        self.errorString = message

class ArithmeticEngine:
    def performCalculation(self, operandOne, operation, operandTwo):
        if operation.operatorChar == '+':
            return CalculationResult(operandOne.numericValue + operandTwo.numericValue)
        elif operation.operatorChar == '-':
            return CalculationResult(operandOne.numericValue - operandTwo.numericValue)
        elif operation.operatorChar == '*':
            return CalculationResult(operandOne.numericValue * operandTwo.numericValue)
        elif operation.operatorChar == '/':
            if operandTwo.numericValue == 0:
                return ErrorMessage('Error')
            return CalculationResult(operandOne.numericValue / operandTwo.numericValue)
        else:
            return ErrorMessage('Error')

def simple_calculator(num1, operator, num2):
    firstNumber = NumberOperand(num1)
    secondNumber = NumberOperand(num2)
    operationType = OperationSymbol(operator)
    calculatorEngine = ArithmeticEngine()

    computationOutcome = calculatorEngine.performCalculation(firstNumber, operationType, secondNumber)

    if isinstance(computationOutcome, CalculationResult):
        return computationOutcome.calculatedValue
    elif isinstance(computationOutcome, ErrorMessage):
        return computationOutcome.errorString

