import re

class SentenceProcessor:
    def __init__(self, raw_text):
        self.raw_text = raw_text

    def process_text(self):
        sentence_separator = SentenceSeparator(self.raw_text)
        separated_sentences = sentence_separator.split_into_sentences()
        processed_parts = []
        for sentence_part in separated_sentences:
            capitalizer = SentenceCapitalizer(sentence_part)
            processed_parts.append(capitalizer.capitalize_first())
        combiner = SentenceCombiner(processed_parts)
        return combiner.join_sentences()

class SentenceSeparator:
    def __init__(self, full_text):
        self.full_text = full_text

    def split_into_sentences(self):
        return re.split(r'([.!?])', self.full_text)

class SentenceCapitalizer:
    def __init__(self, sentence_fragment):
        self.sentence_fragment = sentence_fragment

    def capitalize_first(self):
        stripped_fragment = self.sentence_fragment.strip()
        if not stripped_fragment:
            return ""
        return stripped_fragment[0].upper() + stripped_fragment[1:]

class SentenceCombiner:
    def __init__(self, sentence_list):
        self.sentence_list = sentence_list

    def join_sentences(self):
        result_parts = []
        punctuation_collector = PunctuationCollector()
        for i, part in enumerate(self.sentence_list):
            if part in ['.', '!', '?']:
                punctuation_collector.add_punctuation(part)
            else:
                if punctuation_collector.has_punctuation():
                    result_parts.append(punctuation_collector.get_punctuation())
                    punctuation_collector.clear_punctuation()
                if result_parts and not re.match(r'[.!?]\s*$', result_parts[-1]):
                    result_parts.append(" ")
                result_parts.append(part)
        if punctuation_collector.has_punctuation():
            result_parts.append(punctuation_collector.get_punctuation())
        return "".join(result_parts).strip()

class PunctuationCollector:
    def __init__(self):
        self._punctuation_buffer = []

    def add_punctuation(self, punc_char):
        self._punctuation_buffer.append(punc_char)

    def get_punctuation(self):
        return "".join(self._punctuation_buffer)

    def has_punctuation(self):
        return bool(self._punctuation_buffer)

    def clear_punctuation(self):
        self._punctuation_buffer = []

def capitalize_sentences(text):
    text_processor = SentenceProcessor(text)
    return text_processor.process_text()

