class CharacterCounter:
    def __init__(self, char_value):
        self.char_value = char_value
        self.count_value = 0
        self.first_appearance_index = -1

class CharacterOccurrence:
    def __init__(self, char_value, count_value, first_index):
        self.char_value = char_value
        self.count_value = count_value
        self.first_index = first_index

class MostFrequentFinder:
    def __init__(self, char_map):
        self.char_map = char_map
        self.max_occurrence = None

    def find_most_frequent(self):
        for char_obj in self.char_map.values():
            current_occurrence = CharacterOccurrence(char_obj.char_value, char_obj.count_value, char_obj.first_appearance_index)
            if self.max_occurrence is None or current_occurrence.count_value > self.max_occurrence.count_value:
                self.max_occurrence = current_occurrence
            elif current_occurrence.count_value == self.max_occurrence.count_value and current_occurrence.first_index < self.max_occurrence.first_index:
                self.max_occurrence = current_occurrence
        return self.max_occurrence.char_value

class TextProcessor:
    def __init__(self, input_text):
        self.input_text = input_text
        self.char_trackers = {}

    def process_text(self):
        for index, char in enumerate(self.input_text):
            if char.isspace():
                continue
            lower_char = char.lower()
            if lower_char not in self.char_trackers:
                self.char_trackers[lower_char] = CharacterCounter(lower_char)
                self.char_trackers[lower_char].first_appearance_index = index
            self.char_trackers[lower_char].count_value += 1

        frequency_finder = MostFrequentFinder(self.char_trackers)
        return frequency_finder.find_most_frequent()

def most_frequent_char(text):
    text_processor_instance = TextProcessor(text)
    return text_processor_instance.process_text()

