class GameMove:
    def __init__(self, move_name):
        self.moveName = move_name

class RoundOutcome:
    def __init__(self, outcome_message):
        self.outcomeMessage = outcome_message

class WinCondition:
    def __init__(self, winning_move, losing_move):
        self.winningMove = winning_move
        self.losingMove = losing_move

class GamePlayer:
    def __init__(self, player_number):
        self.playerNumber = player_number

class GameRound:
    def __init__(self, player1_choice, player2_choice):
        self.player1Choice = player1_choice
        self.player2Choice = player2_choice

def rock_paper_scissors(player1_choice, player2_choice):
    player1 = GamePlayer(1)
    player2 = GamePlayer(2)
    current_round = GameRound(GameMove(player1_choice), GameMove(player2_choice))

    win_conditions = [
        WinCondition("rock", "scissors"),
        WinCondition("scissors", "paper"),
        WinCondition("paper", "rock")
    ]

    if current_round.player1Choice.moveName == current_round.player2Choice.moveName:
        return RoundOutcome("It's a tie!").outcomeMessage

    for condition in win_conditions:
        if (current_round.player1Choice.moveName == condition.winningMove and
                current_round.player2Choice.moveName == condition.losingMove):
            return RoundOutcome(f"Player {player1.playerNumber} wins!").outcomeMessage
        elif (current_round.player2Choice.moveName == condition.winningMove and
              current_round.player1Choice.moveName == condition.losingMove):
            return RoundOutcome(f"Player {player2.playerNumber} wins!").outcomeMessage

