class TimeComponent:
    def __init__(self, value):
        self.value = value

    def get_formatted_value(self):
        return f"{self.value:02d}"

class SecondCount:
    def __init__(self, total_seconds):
        self.total_seconds = total_seconds

class HourComponent(TimeComponent):
    def __init__(self, total_seconds):
        super().__init__(total_seconds // 3600)

class MinuteComponent(TimeComponent):
    def __init__(self, total_seconds):
        super().__init__((total_seconds % 3600) // 60)

class SecondComponent(TimeComponent):
    def __init__(self, total_seconds):
        super().__init__(total_seconds % 60)

def seconds_to_hms(total_seconds):
    initial_seconds = SecondCount(total_seconds)
    hours = HourComponent(initial_seconds.total_seconds)
    minutes = MinuteComponent(initial_seconds.total_seconds)
    seconds = SecondComponent(initial_seconds.total_seconds)
    return f"{hours.get_formatted_value()}:{minutes.get_formatted_value()}:{seconds.get_formatted_value()}"

