class StockHolding:
    def __init__(self, tickerSymbol, shareQuantity):
        self.tickerSymbol = tickerSymbol
        self.shareQuantity = shareQuantity

class MarketPrice:
    def __init__(self, tickerSymbol, currentPrice):
        self.tickerSymbol = tickerSymbol
        self.currentPrice = currentPrice

class PortfolioItem:
    def __init__(self, tickerSymbol, valueAmount):
        self.tickerSymbol = tickerSymbol
        self.valueAmount = valueAmount

class PortfolioValueCalculator:
    def calculate(self, holdings, marketPrices):
        totalValue = 0
        for holding in holdings:
            for price in marketPrices:
                if holding.tickerSymbol == price.tickerSymbol:
                    totalValue += holding.shareQuantity * price.currentPrice
        return totalValue

class PortfolioSummary:
    def __init__(self, totalValue):
        self.totalValue = totalValue

def portfolio_value(stocks, prices):
    holdingList = [StockHolding(ticker, quantity) for ticker, quantity in stocks.items()]
    priceList = [MarketPrice(ticker, price) for ticker, price in prices.items()]

    calculatorInstance = PortfolioValueCalculator()
    calculatedValue = calculatorInstance.calculate(holdingList, priceList)
    summaryInstance = PortfolioSummary(calculatedValue)
    return summaryInstance.totalValue

