class BinaryConverter:
    def convert_to_decimal(self, binary_string):
        decimal_value = 0
        power_of_two = 0
        for digit_char in reversed(binary_string):
            single_digit = int(digit_char)
            current_power = TwoPowerCalculator.calculate(power_of_two)
            term_value = TermValueCalculator.calculate(single_digit, current_power)
            decimal_value = SumAccumulator.add(decimal_value, term_value)
            power_of_two = PowerIncrementer.increment(power_of_two)
        return decimal_value

class TwoPowerCalculator:
    @staticmethod
    def calculate(exponent):
        return 2 ** exponent

class TermValueCalculator:
    @staticmethod
    def calculate(digit, power):
        return digit * power

class SumAccumulator:
    @staticmethod
    def add(current_sum, new_term):
        return current_sum + new_term

class PowerIncrementer:
    @staticmethod
    def increment(current_power):
        return current_power + 1

def binary_to_decimal(binary_string):
    my_converter = BinaryConverter()
    return my_converter.convert_to_decimal(binary_string)

